"""Load train/val folders, aug only on train, on the fly."""
from pathlib import Path

import numpy as np
import tensorflow as tf
from tensorflow.keras.applications.resnet import preprocess_input

from .augmentations import build_augmenter


# Keep these IDs fixed: they are the labels expected by the GRL domain head.
DOMAIN_NAMES = ("clean", "pgd", "pixle", "pgd_pixle")
DOMAIN_TO_ID = {name: index for index, name in enumerate(DOMAIN_NAMES)}

# Prefixes are generated by data_preparation/combine_datasets.py. Put the
# combined-attack prefix first so it can never be mistaken for a single attack.
DOMAIN_PREFIXES = (
    ("data_pgdpixle_", "pgd_pixle"),
    ("data_updated_pgd_", "pgd"),
    ("data_updated_pixle_", "pixle"),
    ("data_updated_", "clean"),
)


def domain_id_from_filename(filename):
    """Return the stable domain ID encoded by a combined-dataset filename."""
    basename = Path(filename).name
    for prefix, domain_name in DOMAIN_PREFIXES:
        if basename.startswith(prefix):
            return DOMAIN_TO_ID[domain_name]
    raise ValueError(
        f"Cannot infer domain from filename {basename!r}; expected one of "
        f"{[prefix for prefix, _ in DOMAIN_PREFIXES]}"
    )


def _is_true(value):
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() in ("1", "true", "yes", "y", "on")


def compute_class_weights(config, class_names):
    """Count train images per class and make balanced weights.

    weight = total / (num_classes * count)
    So rare classes get bigger weight. Returns None if turned off.
    """
    mode = str(config.get("class_weight", "none")).lower()
    if mode in ("none", "off", "false", ""):
        return None

    train_dir = Path(config["data"]) / "train"
    counts = []
    for name in class_names:
        folder = train_dir / name
        if not folder.exists():
            counts.append(0)
            continue
        # count image files only
        n = sum(1 for path in folder.iterdir() if path.is_file())
        counts.append(n)

    total = sum(counts)
    num_classes = len(class_names)
    weights = {}
    for i, n in enumerate(counts):
        if n > 0:
            weights[i] = total / (num_classes * n)
        else:
            weights[i] = 1.0

    print(f"Train counts: {dict(zip(class_names, counts))}")
    print(f"Class weights: {weights}")
    return weights


def build_datasets(config):
    """Make train/validation datasets, optionally with class and domain labels.

    With ``grl.enabled: true``, targets contain ``class_output`` and
    ``domain_output`` keys. The default single-output classifier behavior is
    retained when GRL is disabled.
    """
    data_dir = config["data"]
    image_size = int(config.get("image_size", 224))
    batch = int(config.get("batch", 32))
    seed = int(config.get("seed", 4266))
    workers = int(config.get("workers", 0) or 0)
    grl_config = config.get("grl", {}) or {}
    include_domain_labels = _is_true(config.get("include_domain_labels", False)) or _is_true(
        grl_config.get("enabled", False)
    )
    if include_domain_labels and int(grl_config.get("num_domains", 4)) != len(
        DOMAIN_NAMES
    ):
        raise ValueError(
            f"Expected {len(DOMAIN_NAMES)} domain classes to match filename prefixes."
        )

    parallel = tf.data.AUTOTUNE if workers > 0 else 1

    augmenter = build_augmenter(config, image_size=image_size)
    if augmenter is None:
        print("Augmentations OFF: train gets resize + preprocess only")
    else:
        print("Augmentations ON: train gets on-the-fly aug")

    def aug_fn(image, labels):
        def _aug(img):
            img = np.array(img).astype("uint8")
            out = augmenter(image=img)["image"]
            return out.astype("uint8")

        aug_img = tf.numpy_function(_aug, [image], tf.uint8)
        aug_img.set_shape((image_size, image_size, 3))
        return aug_img, labels

    def prep_fn(image, labels):
        image = preprocess_input(tf.cast(image, tf.float32))
        return image, labels

    def add_domain_targets(dataset, file_paths):
        domain_ids = [domain_id_from_filename(path) for path in file_paths]
        domain_ds = tf.data.Dataset.from_tensor_slices(
            tf.convert_to_tensor(domain_ids, dtype=tf.int32)
        )

        def make_targets(image_and_class, domain_id):
            image, class_id = image_and_class
            return image, {
                "class_output": class_id,
                "domain_output": domain_id,
            }

        return tf.data.Dataset.zip((dataset, domain_ds)).map(
            make_targets, num_parallel_calls=parallel
        )

    train_dir = f"{data_dir}/train"
    val_dir = f"{data_dir}/val"

    train_ds = tf.keras.utils.image_dataset_from_directory(
        train_dir,
        labels="inferred",
        label_mode="int",
        image_size=(image_size, image_size),
        batch_size=None,
        # Domain labels are attached by file order below, so defer shuffling
        # until after that step. Preserve the original loader behavior otherwise.
        shuffle=not include_domain_labels,
        seed=seed,
    )
    class_names = train_ds.class_names
    num_classes = len(class_names)
    print(f"Found {num_classes} classes: {class_names}")
    if include_domain_labels:
        train_ds = add_domain_targets(train_ds, train_ds.file_paths)
        print(f"Domain labels enabled: {dict(DOMAIN_TO_ID)}")

    # train gets aug on the fly, then preprocess
    # augment false = resize + preprocess only, same as val
    if augmenter is not None:
        train_ds = train_ds.map(aug_fn, num_parallel_calls=parallel)
    train_ds = train_ds.map(prep_fn, num_parallel_calls=parallel)
    train_ds = train_ds.shuffle(1000, seed=seed).batch(batch).prefetch(tf.data.AUTOTUNE)

    val_ds = tf.keras.utils.image_dataset_from_directory(
        val_dir,
        labels="inferred",
        label_mode="int",
        image_size=(image_size, image_size),
        batch_size=None,
        shuffle=False,
    )
    if include_domain_labels:
        val_ds = add_domain_targets(val_ds, val_ds.file_paths)
    val_ds = val_ds.map(prep_fn, num_parallel_calls=parallel)
    val_ds = val_ds.batch(batch).prefetch(tf.data.AUTOTUNE)

    return train_ds, val_ds, class_names, num_classes
